mapper.delete:
delete from tea_favorite
where f_no in

	#{no}

mapper.select:
select f.f_no as ca_no, f.f_no as f_no, f.p_no as p_no, p.p_name as p_name, p.p_price as ca_price, p.p_img as ca_image, 1 as ca_qty
from tea_favorite f join tea_product p
on f.p_no = p.p_no
where f.m_no = #{m_no} 
and f.f_no in

	#{f_no}
